class NumeroBase {
public:
    explicit NumeroBase(int numero) : numero_{numero} {}
    int numero() const { return numero_; }
    void cambiar(int numero) { numero_ = numero; }
private:
    int numero_;
};

class NumeroCerrado final : public NumeroBase {
public:
    explicit NumeroCerrado(int numero) : NumeroBase{numero} {}
};

